function e(e,t){let n=e.hostname||e.device_id,r=e.value;if(r==null)return e.title||e.message;switch(e.rule_type){case`disk_low`:return t(`alerts.text_disk_low`,{host:n,free:r.toFixed(1),threshold:e.threshold??``});case`device_offline`:return t(`alerts.text_offline`,{host:n,minutes:Math.round(r)});case`critical_patch`:return t(`alerts.text_patches`,{host:n,count:Math.round(r)});default:return e.title||e.message}}function t(e,t){return e.type===`low_disk`&&e.value!==null&&e.value!==void 0?t(`dashboard.alert_low_disk`,{free:e.value.toFixed(1)}):e.type===`offline_long`?t(`dashboard.alert_offline_since`,{date:new Date(e.timestamp).toLocaleString()}):e.message}export{e as n,t};